 // Count each physical CAD identity once; display names are not material identities.
 public sealed class BatchMaterialIdentity012 {
  readonly HashSet<Guid> prior=new HashSet<Guid>(),material=new HashSet<Guid>(),accepted=new HashSet<Guid>();
  static Guid Id(string value){if(!Guid.TryParse(value,out var id)||id==Guid.Empty)throw new InvalidDataException("Actual nonempty workpiece GUID required.");return id;}
  public BatchMaterialIdentity012(string[] priorIds){foreach(string value in priorIds??throw new InvalidDataException("Sealed prior acceptance evidence required."))if(!prior.Add(Id(value)))throw new InvalidDataException("Duplicate prior accepted ID.");}
  public int MaterialCount=>material.Count;public int AcceptedCount=>accepted.Count;
  public void RegisterMaterial(string value){Guid id=Id(value);if(prior.Contains(id)||material.Contains(id)||material.Count>=20)throw new InvalidDataException("Reused/prior material ID or more than20 actual material parts.");material.Add(id);}
  public void AcceptC2(string value){Guid id=Id(value);if(!material.Contains(id)||accepted.Contains(id))throw new InvalidDataException("C2 acceptance requires a distinct actual registered material part.");accepted.Add(id);}
 }
 public sealed class WorkpieceRecord {
  public Part Part;public int Sequence;public string Phase="Available";public int Slot=-1;public Matrix4 SpawnPose;public string Id=>Part.UniqueId.ToString();
 }
 public sealed class CellCodeBehind:SmartComponentCodeBehind,IDisposable {
  CellRuntime runtime;
  public override void OnInitialize(SmartComponent component){
   // Loading a Pack & Go is passive. Only the explicit button grants UI preparation.
   if(!component.StateCache.TryGetValue("MA6212.DemoPrepareOnUI",out object allowed)||allowed is not true||SynchronizationContext.Current is not System.Windows.Forms.WindowsFormsSynchronizationContext){component.StateCache["MA6212.Armed"]=false;component.StateCache["MA6212.BootstrapState"]="WAITING_FOR_PREPARE_BUTTON";return;}
   if(component.StateCache.TryGetValue("MA6212.Runtime",out object old)){runtime=old as CellRuntime;if(runtime==null)throw new InvalidOperationException("Existing actor belongs to another context; no implicit replacement");return;}
   var config=JsonSerializer.Deserialize<ActorConfig>(component.Assets.Single(a=>a.Name=="MA6212.ActorConfig.json").GetData());
   if(config.Armed)throw new InvalidOperationException("Persisted actor must be unarmed; no silent reset");
   runtime=new CellRuntime(component,config);component.StateCache["MA6212.Runtime"]=runtime;component.StateCache["MA6212.Dispose"]=(Action)runtime.Dispose;component.StateCache["MA6212.Arm"]=(Action<bool>)runtime.Arm;
  }
  public override void OnSimulationStart(SmartComponent component){runtime?.Start();}
  public override void OnSimulationStop(SmartComponent component){runtime?.Stopped();}
  public override void OnIOSignalValueChanged(SmartComponent component,IOSignal changedSignal){runtime?.QueueSignal(changedSignal.Name,changedSignal.Value);}
  public override SimulationActorState QuerySimulationState(SmartComponent component)=>runtime!=null&&runtime.Armed&&!runtime.Faulted?SimulationActorState.Passive:SimulationActorState.Stopped;
  public override double QuerySimulationStep(SmartComponent component,double previousTime)=>runtime!=null&&runtime.Armed?20:0;
  public override System.Threading.Tasks.Task OnSimulationStepEndAsync(SmartComponent component,double simulationTime){runtime?.Step(simulationTime);return System.Threading.Tasks.Task.CompletedTask;}
  public void Dispose(){runtime?.Dispose();}
 }
 public sealed class CellRuntime:IDisposable {
