  static string MeshFingerprint(Part part){var mesh=part.Mesh;var info=mesh.GetInfo();if(info.NumberOfTriangles<=0||info.NumberOfVertices<=0)throw new InvalidDataException("Actual CAD mesh must contain triangles and vertices; BodyCount may be zero for imported library meshes.");var b=part.GetBoundingBox(false);double[] bounds={b.min.x,b.min.y,b.min.z,b.max.x,b.max.y,b.max.z};if(bounds.Any(v=>!double.IsFinite(v))||b.max.x<=b.min.x||b.max.y<=b.min.y||b.max.z<=b.min.z)throw new InvalidDataException("Finite positive local CAD bounds required");var text=new System.Text.StringBuilder();text.Append("bodies=").Append(part.Bodies.Count).Append(";vertices=").Append(info.NumberOfVertices).Append(";triangles=").Append(info.NumberOfTriangles).Append(';');foreach(double v in bounds)text.Append(v.ToString("R",CultureInfo.InvariantCulture)).Append(';');int faces=0,vertices=0,indices=0;mesh.TraverseFaces(face=>{var vs=face.Vertices.ToArray();var ix=face.TriangleIndices.ToArray();if(ix.Length%3!=0||ix.Any(i=>i<0||i>=vs.Length))throw new InvalidDataException("Actual mesh triangle index range invalid");text.Append("face:").Append(vs.Length).Append('/').Append(ix.Length).Append(';');foreach(var v in vs){if(!double.IsFinite(v.x)||!double.IsFinite(v.y)||!double.IsFinite(v.z))throw new InvalidDataException("Nonfinite actual mesh vertex");text.Append(v.x.ToString("R",CultureInfo.InvariantCulture)).Append(',').Append(v.y.ToString("R",CultureInfo.InvariantCulture)).Append(',').Append(v.z.ToString("R",CultureInfo.InvariantCulture)).Append(';');}foreach(int index in ix)text.Append(index.ToString(CultureInfo.InvariantCulture)).Append(',');faces++;vertices+=vs.Length;indices+=ix.Length;});if(faces==0||vertices==0||indices==0)throw new InvalidDataException("Traversed actual mesh must contain real triangle geometry");return Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(text.ToString())));}
  void CheckTemplate(){if(MeshFingerprint(feedTemplate)!=templateMeshFingerprint)throw new InvalidDataException("Independent template CAD mesh changed");if(Object.ReferenceEquals(feedTemplate,prototype)||feedTemplate.UniqueId==prototype.UniqueId||feedTemplate.ContainingProject!=null||station.GraphicComponents.Contains(feedTemplate))throw new InvalidDataException("Feed template must be independent nonactive CAD, never a material part.");var b=feedTemplate.GetBoundingBox(false);double[] values={b.min.x,b.min.y,b.min.z,b.max.x,b.max.y,b.max.z};double[] expected={templateBounds.min.x,templateBounds.min.y,templateBounds.min.z,templateBounds.max.x,templateBounds.max.y,templateBounds.max.z};if(values.Any(v=>!double.IsFinite(v))||b.max.x<=b.min.x||b.max.y<=b.min.y||b.max.z<=b.min.z||values.Where((v,i)=>System.Math.Abs(v-expected[i])>worldPosition).Any())throw new InvalidDataException("Independent CAD template geometry changed.");}
