    if(stable){if(!VacuumContactRules.TryAttachKeepWorld(station,tool,candidate.piece.Part,tcp,candidate.frame,contactPosition,contactAngle,worldPosition,worldAngle,out Matrix4 before,out Matrix4 after,out string diagnostic))throw new InvalidOperationException(diagnostic);held=candidate.piece;heldContact=candidate.contact;held.Phase="Held";state="Held_"+heldContact;Hook<Action<Part>>("MA6212.HeldPartHook")(held.Part);Output("diVacuumOK",true);Write("actual_contact_and_attachment_verified",time,new{id=held.Id,contact=heldContact,actualBefore=before.Elements,actualAfter=after.Elements});}
    else Output("diVacuumOK",false);
   }else{gate.Reset();Output("diVacuumOK",false);}
   if(feed&&feedArmed&&held==null&&!pieces.Any(p=>p.Phase=="Available"||p.Phase=="AtFixture"||p.Phase=="Held")){
    if(cfg.AllowFeed&&fed<cfg.MaximumParts&&AtReady()){feedArmed=false;CheckTemplate();var part=(Part)feedTemplate.CopyInstance();if(MeshFingerprint(part)!=templateMeshFingerprint)throw new InvalidDataException("New feed instance actual mesh differs from independent CAD template");if(part.UniqueId==feedTemplate.UniqueId)throw new InvalidDataException("Material instance must have its own actual ID.");part.Name="MA6212_Part_"+cfg.RunId+"_"+(fed+1);Matrix4 spawn=source;Vector3 v=spawn.Translation;v.x+=offsets[fed][0]/1000;v.y+=offsets[fed][1]/1000;spawn.Translation=v;part.Transform.GlobalMatrix=spawn;station.GraphicComponents.Add(part);fed++;var record=new WorkpieceRecord{Part=part,Sequence=fed,SpawnPose=spawn,Phase="FeedPendingRegistration"};pieces.Add(record);if(!CollisionHook(part,true))throw new InvalidOperationException("Dynamic collision registration did not confirm new part.");if(!At(part,spawn)||AttachmentPresent(record))throw new InvalidOperationException("New CAD feed pose/attachment readback failed.");Support(part,"Source",spawn);identities.RegisterMaterial(record.Id);record.Phase="Available";state="PartAvailable";Write("actual_cad_feed_created",time,new{id=record.Id,sequence=fed,offsetMm=offsets[fed-1],actualWorld=part.Transform.GlobalMatrix.Elements});}
