   }
   if(!Hook<Func<double,bool>>("MA6212.CollisionCheckNow")(time))throw new InvalidOperationException("Actual collision CheckNow failed.");bool available=pieces.Any(p=>p.Phase=="Available"&&At(p.Part,p.SpawnPose)&&!AttachmentPresent(p));if(feed&&!feedAcknowledged&&available&&held==null&&AtReady()){feedAcknowledged=true;feedArmed=false;}Output("diFeedReady",feed&&feedAcknowledged);Output("diBoxReady",clear&&boxAcknowledged);Summary();Write("step_end",time,new{actualSourceAvailable=available,actualGeometryPackedCount=pieces.Count(p=>p.Phase=="Packed"),actualCumulativeGeometryPackedCount=acceptedPackedIds.Count,actualArchivedCount=pieces.Count(p=>p.Phase=="Archived"),feedAcknowledgement=feed&&feedAcknowledged,clearAcknowledgement=clear&&boxAcknowledged});
  }catch(Exception e){Fault("step",e,time);}}
  bool CollisionHook(Part part,bool add){if(sc.StateCache.TryGetValue("MA6212.CollisionWorkpieceHook",out object hook)&&hook is Func<Part,bool,bool> register)return register(part,add);return false;}
  void CheckBoxOccupancy(){foreach(var p in pieces.Where(p=>p.Phase=="Packed"))if(AttachmentPresent(p)||!At(p.Part,slots[p.Slot]))throw new InvalidOperationException("Previously packed workpiece moved or became attached.");foreach(var part in station.GraphicComponents.OfType<Part>().Where(p=>p.Name!="VacuumTool"&&!equipmentNames.Contains(p.Name))){var b=part.GetBoundingBox(true);bool intersects=b.min.x<boxInterior.max.x&&b.max.x>boxInterior.min.x&&b.min.y<boxInterior.max.y&&b.max.y>boxInterior.min.y&&b.min.z<boxInterior.max.z&&b.max.z>boxInterior.min.z;if(!intersects)continue;var record=pieces.SingleOrDefault(p=>Object.ReferenceEquals(p.Part,part));if(record==null||(record.Phase!="Packed"&&record.Phase!="Held"))throw new InvalidOperationException("Unclassified actual workpiece/object occupies box; no ready/clear success.");}}
  void Summary(){if(identities!=null&&identities.AcceptedCount!=acceptedPackedIds.Count)throw new InvalidDataException("Actual C2 identity accounting diverged.");sc.StateCache["MA6212.ActualMaterialIdCount"]=identities?.MaterialCount??0;sc.StateCache["MA6212.PriorAcceptedIdCount"]=cfg.PriorAcceptedPartIds?.Length??0;sc.StateCache["MA6212.PriorAcceptedIdsEvidenceSha256"]=cfg.PriorAcceptedIdsEvidenceSha256;sc.StateCache["MA6212.ActorState"]=state;sc.StateCache["MA6212.IsHolding"]=held!=null;sc.StateCache["MA6212.Faulted"]=Faulted;sc.StateCache["MA6212.FedCount"]=fed;sc.StateCache["MA6212.GeometryPackedCount"]=pieces.Count(p=>p.Phase=="Packed");sc.StateCache["MA6212.ActiveBoxGeometryPackedCount"]=pieces.Count(p=>p.Phase=="Packed");sc.StateCache["MA6212.CumulativeGeometryPackedCount"]=acceptedPackedIds.Count;sc.StateCache["MA6212.GeometryArchivedCount"]=pieces.Count(p=>p.Phase=="Archived");}
  object ControllerFeedback()=>new[]{"diVacuumOK","diFeedReady","diBoxReady"}.ToDictionary(n=>n,n=>{var s=task.IOSignals.FirstOrDefault(s=>s.Name==n);return s==null?null:s.Value;});
  void Write(string kind,double time,object detail){if(log==null)return;Matrix4 actualTcp=Tcp();var partData=pieces.Where(p=>p.Phase!="Archived").Select(p=>new{id=p.Id,p.Sequence,p.Phase,p.Slot,actualWorld=p.Part.Transform.GlobalMatrix.Elements,attachedToTool=VacuumContactRules.ActuallyAttached(station,tool,p.Part),c1Error=VacuumContactRules.Error(actualTcp,VacuumContactRules.CurrentContact(p.Part,c1)),c2Error=VacuumContactRules.Error(actualTcp,VacuumContactRules.CurrentContact(p.Part,c2))}).ToArray();log.WriteLine(JsonSerializer.Serialize(new{kind,virtualTimeMs=time,state,cumulativeGeometryPackedCount=acceptedPackedIds.Count,activeBoxGeometryPackedCount=pieces.Count(p=>p.Phase=="Packed"),geometryArchivedCount=pieces.Count(p=>p.Phase=="Archived"),actualTcpWorld=actualTcp.Elements,scSignals=sc.IOSignals.ToDictionary(s=>s.Name,s=>s.Value),controllerFeedback=ControllerFeedback(),parts=partData,detail},new JsonSerializerOptions{IncludeFields=true}));if(kind!="step_end"||time%250<20)log.Flush();}
  void Fault(string phase,Exception e,double time){if(Environment.CurrentManagedThreadId!=uiThread){if(Interlocked.Exchange(ref faultQueued,1)==0)ui.Post(_=>Fault(phase,e,time),null);return;}Faulted=true;state="Fault";sc.StateCache["MA6212.LastFault"]=e.ToString();Summary();try{Output("diFeedReady",false);Output("diBoxReady",false);Output("diVacuumOK",held!=null&&Input("doVacuum")&&VacuumContactRules.ActuallyAttached(station,tool,held.Part)&&VacuumContactRules.Error(Tcp(),VacuumContactRules.CurrentContact(held.Part,heldContact=="C1"?c1:c2)).Within(contactPosition,contactAngle));Write("fault",time,new{phase,error=e.ToString()});log?.Flush();}catch{}if(!pauseQueued){pauseQueued=true;ui?.Post(async _=>{try{await Simulator.PauseAsync();}catch(Exception error){sc.StateCache["MA6212.PauseError"]=error.ToString();}},null);}}
  public void Stopped(){if(!started)return;try{CheckUi();Write("simulation_stop",Simulator.CurrentTime,new{holding=held!=null});log?.Flush();}catch(Exception e){sc.StateCache["MA6212.StopError"]=e.ToString();}}
  public void Dispose(){if(disposed)return;disposed=true;log?.Flush();log?.Dispose();}
 }
}
